def transform(grid):
    """Trace a beam through aligned openings in walls of color 8."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not seeds:
        return out
    r, c = seeds[0]
    if r == 0:
        dr, dc = 1, 0
    elif r == h - 1:
        dr, dc = -1, 0
    elif c == 0:
        dr, dc = 0, 1
    else:
        dr, dc = 0, -1

    def inside(y, x):
        return 0 <= y < h and 0 <= x < w

    def paint(y, x):
        if grid[y][x] != 8:
            out[y][x] = 2

    pending = [(r, c, dr, dc)]
    visited = set()
    while pending:
        y, x, dy, dx = pending.pop()
        state = (y, x, dy, dx)
        if state in visited:
            continue
        visited.add(state)
        paint(y, x)
        while True:
            ny, nx = y + dy, x + dx
            if not inside(ny, nx):
                break
            if grid[ny][nx] != 8:
                y, x = ny, nx
                paint(y, x)
                continue

            # A wall blocks forward travel. Follow its near face in both
            # directions, to the nearest opening (or the grid edge), then
            # send a ray through each opening in the original direction.
            for side in (-1, 1):
                sy, sx = y, x
                while True:
                    if dy != 0:
                        sx += side
                    else:
                        sy += side
                    if not inside(sy, sx) or grid[sy][sx] == 8:
                        break
                    paint(sy, sx)
                    wy, wx = sy + dy, sx + dx
                    if not inside(wy, wx):
                        break
                    if grid[wy][wx] != 8:
                        paint(wy, wx)
                        pending.append((wy, wx, dy, dx))
                        break
            break
    return out
